//! Checks the merge against QuPath's own output.
//!
//! Fixture generated by `parity/java/MergeAndSplit.java` via
//! `./parity/record.sh`, recorded through the three lines detection runs on the
//! binary the intensity filter leaves:
//!
//! ```java
//! bp.filter(ImageProcessor.MAX);
//! bp.copyBits(bpLoG, 0, 0, Blitter.AND);
//! List<PolygonRoi> rois2 = RoiLabeling.getFilledPolygonROIs(bp, Wand.FOUR_CONNECTED);
//! bp.setValue(255);
//! for (Roi r : rois2)
//!     bp.fill(r);
//! ```
//!
//! followed by `new EDM().toWatershed(bp)`. Needs no slide.
//!
//! Four checkpoints are asserted, not one, because each is a separable piece of
//! work and a single end-to-end mask would say only that something disagrees:
//!
//! - `merged` — after the dilation, the AND and the hole fill;
//! - `edm` — the float distance map, compared **by its bits**;
//! - `maxima` — the segmentation `MaximumFinder` derives from it;
//! - `segmented` — the mask `toWatershed` leaves behind.
//!
//! Masks are compared pixel for pixel, and two counts are asserted alongside
//! them: the merged region count, and the object count after the split. The
//! second is the number the whole stage exists to change, and a mask can agree
//! everywhere and still trace to a different number of objects if one pixel of
//! a segmentation line is misplaced.

use qupath_pipeline::{FOREGROUND, Merger};
use qupath_watershed::{DistanceMap, RegionTracer, Segmenter};

fn fixture() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../parity/fixtures/MergeAndSplit.json")
}

/// Extracts the text between two markers, starting the search at `from`.
fn between<'a>(haystack: &'a str, start: &str, end: &str, from: usize) -> (&'a str, usize) {
    let open = haystack[from..].find(start).expect(start) + from + start.len();
    let close = haystack[open..].find(end).expect(end) + open;
    (&haystack[open..close], close)
}

fn floats(text: &str) -> Vec<f32> {
    if text.trim().is_empty() {
        return Vec::new();
    }
    text.split(',')
        .map(|v| v.trim().parse().expect("float"))
        .collect()
}

fn ints(text: &str) -> Vec<u32> {
    if text.trim().is_empty() {
        return Vec::new();
    }
    text.split(',')
        .map(|v| v.trim().parse().expect("integer"))
        .collect()
}

fn scalar(text: &str, key: &str, from: usize) -> (f64, usize) {
    let (value, at) = between(text, &format!("\"{key}\": "), ",", from);
    (value.trim().parse().expect(key), at)
}

#[expect(
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    reason = "recorded dimensions and counts are small positive integers"
)]
fn index(value: f64) -> usize {
    value as usize
}

/// Turns the recorded `bpLoG` back into a Laplacian that thresholds to it.
///
/// The fixture records `SimpleThresholding.thresholdAbove(fpLoG, 0.0)` rather
/// than the float image, because that mask is all the `AND` can see. Any pair of
/// values straddling zero reconstructs it, and the port takes the float image so
/// that the pipeline does not have to materialise the mask.
fn laplacian_from(mask: &[u32]) -> Vec<f32> {
    mask.iter()
        .map(|&v| if v != 0 { 1.0 } else { -1.0 })
        .collect()
}

#[test]
fn matches_qupath_merge() {
    let path = fixture();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e}; run ./parity/record.sh", path.display()));
    let (cases, _) = between(&text, "\"cases\": [", "\n  ]\n}", 0);

    let mut count = 0usize;
    let mut merged_seen = 0u32;
    let mut objects_seen = 0u32;
    let mut at = 0usize;
    // One merger and one tracer across every case: buffers left dirty by a
    // previous case would show up here and nowhere else.
    let mut merger = Merger::new();
    let mut tracer = RegionTracer::new();
    let mut distances = DistanceMap::new();
    let mut segmenter = Segmenter::new();
    while let Some(start) = cases[at..].find("{\"name\": \"") {
        let from = at + start;
        let (name, next) = between(cases, "\"name\": \"", "\"", from);
        let (width, next) = scalar(cases, "width", next);
        let (height, next) = scalar(cases, "height", next);
        let (expected_merged, next) = scalar(cases, "mergedCount", next);
        let (expected_objects, next) = scalar(cases, "objects", next);
        let (binary_text, next) = between(cases, "\"binary\": [", "]", next);
        let (log_text, next) = between(cases, "\"logMask\": [", "]", next);
        let (merged_text, next) = between(cases, "\"merged\": [", "]", next);
        let (edm_text, next) = between(cases, "\"edm\": [", "]", next);
        let (maxima_text, next) = between(cases, "\"maxima\": [", "]", next);
        let (segmented_text, next) = between(cases, "\"segmented\": [", "]", next);
        at = next;

        let (width, height) = (index(width), index(height));
        let recorded = ints(binary_text);
        let log = laplacian_from(&ints(log_text));
        let their_merged = ints(merged_text);

        assert_eq!(recorded.len(), width * height, "{name}: input binary");
        assert_eq!(their_merged.len(), width * height, "{name}: merged binary");

        let mut binary: Vec<u8> = recorded
            .iter()
            .map(|&v| {
                assert!(
                    v == 0 || v == u32::from(FOREGROUND),
                    "{name}: the recorded binary holds {v}, which is neither 0 nor 255"
                );
                u8::try_from(v).expect("0 or 255")
            })
            .collect();

        let found = merger.merge(&mut binary, &log, width, &mut tracer);

        for (at, (&theirs, &ours)) in their_merged.iter().zip(&binary).enumerate() {
            assert_eq!(
                u32::from(ours),
                theirs,
                "{name}: pixel ({}, {}) merges to {ours}, QuPath has {theirs}",
                at % width,
                at / width
            );
        }
        assert_eq!(
            u64::from(found),
            index(expected_merged) as u64,
            "{name}: merged region count"
        );

        // The distance map the shape split runs on, compared bit for bit: a
        // chamfer would be wrong by a percent or two, would look right, and
        // would move the saddle between two touching nuclei by a pixel.
        let their_edm = floats(edm_text);
        // Asserted rather than left to `zip`, which would compare nothing at
        // all and pass if the fixture ever stopped carrying this array.
        assert_eq!(their_edm.len(), width * height, "{name}: recorded EDM");
        let mut ours = vec![0.0f32; binary.len()];
        distances.make_float_edm(&binary, &mut ours, width);
        for (at, (&theirs, &mine)) in their_edm.iter().zip(&ours).enumerate() {
            assert_eq!(
                mine.to_bits(),
                theirs.to_bits(),
                "{name}: pixel ({}, {}) is {mine} from background, QuPath has {theirs}",
                at % width,
                at / width
            );
        }

        // The segmentation MaximumFinder derives from that distance map, and
        // then the mask toWatershed leaves. Both, because the first is where a
        // disagreement is legible and the second is what detection consumes.
        let their_maxima = ints(maxima_text);
        let their_segmented = ints(segmented_text);
        assert_eq!(
            their_maxima.len(),
            width * height,
            "{name}: recorded maxima"
        );
        assert_eq!(
            their_segmented.len(),
            width * height,
            "{name}: recorded segmentation"
        );

        segmenter.find_maxima(&ours, width);
        for (at, (&theirs, &mine)) in their_maxima
            .iter()
            .zip(segmenter.segmentation())
            .enumerate()
        {
            assert_eq!(
                u32::from(mine),
                theirs,
                "{name}: pixel ({}, {}) segments to {mine}, QuPath has {theirs}",
                at % width,
                at / width
            );
        }

        segmenter.segment(&ours, &mut binary, width);
        for (at, (&theirs, &mine)) in their_segmented.iter().zip(&binary).enumerate() {
            assert_eq!(
                u32::from(mine),
                theirs,
                "{name}: pixel ({}, {}) splits to {mine}, QuPath has {theirs}",
                at % width,
                at / width
            );
        }

        // The number the whole stage exists to change. A mask can match
        // everywhere and still be traced into a different number of objects if
        // a single line pixel is misplaced, so this is asserted separately.
        let mut split_regions = vec![0u32; binary.len()];
        let objects = tracer.trace_mask_into(&binary, &mut split_regions, width);
        assert_eq!(
            u64::from(objects),
            index(expected_objects) as u64,
            "{name}: objects after the split"
        );
        objects_seen += objects;

        count += 1;
        merged_seen += found;
    }

    assert_eq!(count, 13, "expected 13 recorded cases");
    assert!(
        merged_seen > 30,
        "the fixture should merge a few dozen regions in total, not {merged_seen}"
    );
    // The split must do real work across the fixture as a whole: it separates
    // 35 merged regions into 92 objects. A port that split nothing would pass
    // every per-case mask comparison on the cases that are single blobs.
    assert!(
        objects_seen > merged_seen * 2,
        "the split should roughly double the object count, {merged_seen} -> {objects_seen}"
    );
}
